begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/stock.inc
create temporary table stock_result(k text primary key,v jsonb);grant all on stock_result to authenticated;
set local role authenticated;
select is((select sum(quantity_delta) from public.stock_movements),100::numeric,'explicit opening is ledger truth');
insert into stock_result values('receipt',pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',25,null,'GRAM','c4000000-0000-4000-8000-000000000201'));
select is((select v#>>'{data,status}' from stock_result where k='receipt'),'SAVED','receipt posts');
select is(pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',25,null,'GRAM','c4000000-0000-4000-8000-000000000201'),(select v from stock_result where k='receipt'),'permanent exact retry returns same result');
select is(pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',26,null,'GRAM','c4000000-0000-4000-8000-000000000201')->>'code','STOCK_CONFLICT','changed retry conflicts');
select is((select sum(quantity_delta) from public.stock_movements),125::numeric,'retry never duplicates quantity');
select is(pg_temp.move('ADJUSTMENT_OUT','c4000000-0000-4000-8000-000000000101',126)->>'code','STOCK_INSUFFICIENT','default blocks negative');
select is(pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',1,null,'MILLILITER')->>'code','UNIT_CONVERSION_REQUIRED','grams are not milliliters');
select is(pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',1.001)->>'code','VALIDATION_FAILED','no silently rounded quantity');
select is(pg_temp.move('OPENING','c4000000-0000-4000-8000-000000000101',10)->>'code','STOCK_CONFLICT','opening cannot be repeated');
select is(pg_temp.stock(jsonb_build_object('type','REVERSAL','mutation_id',gen_random_uuid(),'movement_id',(select v#>>'{data,id}' from stock_result where k='receipt'),'reason','Synthetic correction'))#>>'{data,status}','SAVED','manual history correction appends reversal');
select is((select sum(quantity_delta) from public.stock_movements),100::numeric,'reversal rebuilds balance');
select is(pg_temp.stock(jsonb_build_object('type','REVERSAL','mutation_id',gen_random_uuid(),'movement_id',(select v#>>'{data,id}' from stock_result where k='receipt'),'reason','Repeated correction'))->>'code','STOCK_CONFLICT','one reversal per movement');
select is(pg_temp.item('c4000000-0000-4000-8000-000000000102')#>>'{data,status}','SAVED','custom operational product is allowed');
select is(public.stock_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{"item_id":"c4000000-0000-4000-8000-000000000102"}')#>>'{data,items,0,stock_status}','UNKNOWN','missing opening remains UNKNOWN');
select is(pg_temp.move('OPENING','c4000000-0000-4000-8000-000000000102',0)#>>'{data,status}','SAVED','measured zero opening persists');
select is(public.stock_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{"item_id":"c4000000-0000-4000-8000-000000000102"}')#>>'{data,items,0,stock_status}','OUT','measured zero is OUT, not UNKNOWN');
select is(pg_temp.item('c4000000-0000-4000-8000-000000000103',null,'UNIT')#>>'{data,status}','SAVED','unit item persists');
select is(pg_temp.move('OPENING','c4000000-0000-4000-8000-000000000103',1.5,null,'UNIT')->>'code','UNIT_CONVERSION_REQUIRED','pieces reject fractions');
select is(pg_temp.stock('{"type":"COUNT_CREATE","mutation_id":"c4000000-0000-4000-8000-000000000211","id":"c4000000-0000-4000-8000-000000000301","reason":"Physical count","lines":[{"stock_item_id":"c4000000-0000-4000-8000-000000000101","lot_id":null,"counted_quantity":90}]}')#>>'{data,status}','SAVED','draft records basis and measured quantity');
select is(pg_temp.stock('{"type":"COUNT_CONFIRM","mutation_id":"c4000000-0000-4000-8000-000000000212","id":"c4000000-0000-4000-8000-000000000301","reason":"Confirm physical count"}')#>>'{data,status}','SAVED','confirmation appends adjustment');
select is((select sum(quantity_delta) from public.stock_movements where stock_item_id='c4000000-0000-4000-8000-000000000101'),90::numeric,'confirmed count equals factual balance');
select is(pg_temp.stock('{"type":"COUNT_CONFIRM","mutation_id":"c4000000-0000-4000-8000-000000000213","id":"c4000000-0000-4000-8000-000000000301","reason":"Second confirmation"}')->>'code','STOCK_CONFLICT','confirmed count is immutable');
select is(pg_temp.stock('{"type":"COUNT_CREATE","mutation_id":"c4000000-0000-4000-8000-000000000214","id":"c4000000-0000-4000-8000-000000000302","reason":"Count basis","lines":[{"stock_item_id":"c4000000-0000-4000-8000-000000000101","lot_id":null,"counted_quantity":85}]}')#>>'{data,status}','SAVED','second draft records current basis');
select pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',1);
select is(pg_temp.stock('{"type":"COUNT_CONFIRM","mutation_id":"c4000000-0000-4000-8000-000000000215","id":"c4000000-0000-4000-8000-000000000302","reason":"Stale count"}')->>'code','STOCK_COUNT_STALE','intervening movement prevents stale confirmation');
select is(pg_temp.stock('{"type":"POLICY","mutation_id":"c4000000-0000-4000-8000-000000000216","negative_policy":"WARN_NEGATIVE","expected_version":1,"reason":"Explicit operational exception"}')#>>'{data,status}','SAVED','policy change is controlled');
select is(pg_temp.move('ADJUSTMENT_OUT','c4000000-0000-4000-8000-000000000101',100)#>>'{data,status}','SAVED','WARN permits explicit negative adjustment');
select is(pg_temp.stock('{"type":"ENABLE","mutation_id":"c4000000-0000-4000-8000-000000000217","reason":"Forged","organization_id":"b4000000-0000-4000-8000-000000000002"}')->>'code','VALIDATION_FAILED','forged authority rejected');
select is(pg_temp.stock('{"type":"POLICY","mutation_id":"c4000000-0000-4000-8000-000000000218","negative_policy":"BLOCK_NEGATIVE","expected_version":"2","reason":"Coerced"}')->>'code','VALIDATION_FAILED','raw RPC rejects string version');
select throws_ok($$insert into public.stock_movements select * from public.stock_movements limit 1$$,'42501',null,'normal role cannot forge ledger');
select throws_ok($$update public.stock_movements set quantity_delta=1$$,'42501',null,'normal role cannot rewrite ledger');
select throws_ok($$delete from public.stock_movements$$,'42501',null,'normal role cannot delete ledger');
select throws_ok($$update public.stock_source_events set status='PROCESSED'$$,'42501',null,'normal role cannot forge sync');
select throws_ok($$select app_private.stock_operation_core(null,null,'{}',null)$$,'42501',null,'unguarded core is private');
reset role;
select ok(exists(select 1 from public.audit_events where action='stock.negative_override'),'negative override audited');
select throws_ok($$update public.stock_movements set reason='rewrite'$$,'23514','IMMUTABLE_LIVE_HISTORY','privileged accidental rewrite is blocked');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);set local role authenticated;
select is((select count(*) from public.stock_movements),0::bigint,'cross tenant ledger denied');
select is(public.stock_snapshot('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000012','{"item_id":"c4000000-0000-4000-8000-000000000101"}')->>'code','STOCK_NOT_FOUND','cross tenant detail denied');
reset role;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000023',true);set local role authenticated;
select is(pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',1)->>'code','TENANT_CONTEXT_INVALID','another actor cannot borrow owner context');
select is(public.stock_operation('b4000000-0000-4000-8000-000000000113','b4000000-0000-4000-8000-000000000011','{"type":"ENABLE","mutation_id":"c4000000-0000-4000-8000-000000000219","reason":"No manage permission"}',gen_random_uuid())->>'code','FORBIDDEN','view permission cannot write');
reset role;
update public.salon_memberships set status='revoked',revoked_at=now() where id='b4000000-0000-4000-8000-000000000111';
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);set local role authenticated;
select is((select count(*) from public.stock_movements),0::bigint,'revoked membership sees no ledger');
select is(pg_temp.move('RECEIPT','c4000000-0000-4000-8000-000000000101',1)->>'code','MEMBERSHIP_REVOKED','revoked actor cannot replay writes');
reset role;set local role anon;
select throws_ok($$select * from public.stock_items$$,'42501',null,'anonymous stock read denied');
reset role;
select * from finish();rollback;
